def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather opponent moves
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Perfect cooperator: cooperate, but exploit the very last round
    if opp_d == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # Perfect/high defector: defect
    if opp_c == 0:
        return 'D'
    if opp_c <= 1 and n >= 6:
        return 'D'

    last_opp = opp[-1]

    # Detect sustained defection in recent window
    window = min(n, 8)
    recent = opp[-window:]
    recent_d = recent.count('D')
    recent_c = window - recent_d

    # If opponent heavily defectious lately, defect
    if recent_d >= 6:
        return 'D'
    if recent_d >= 4 and recent_c <= 1:
        return 'D'

    # Detect strict alternation (period 2) and predict/exploit
    if n >= 6:
        alt = True
        for i in range(n - 6, n - 1):
            if opp[i] == opp[i + 1]:
                alt = False
                break
        if alt:
            # Predict next is opposite of last
            return 'D' if last_opp == 'C' else 'C'

    # Detect runs: long D run -> keep defecting; long C run -> cooperate
    run_d = 0
    for x in reversed(opp):
        if x == 'D':
            run_d += 1
        else:
            break
    if run_d >= 2:
        return 'D'

    # Opponent defected last round
    if last_opp == 'D':
        # Mostly cooperative opponent, occasionally forgive first defection
        if opp_c >= n - 2 and n >= 6:
            # Forgive a single recent defection with some probability
            if recent_d == 1 and rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent cooperated last round
    # If we defected last and opponent still cooperated, they are forgiving;
    # exploit a little but not too much
    if me[-1] == 'D':
        # Both defensible: keep exploiting rarely, else restore cooperation
        if opp_d <= 2 and n >= 10:
            return 'C'
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    # Opponent mostly cooperative -> cooperate, with occasional late exploit
    coop_rate = opp_c / n
    if coop_rate >= 0.85:
        if n >= 95:
            return 'D'
        if n >= 20 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mixed opponent: cooperate if recent is friendly, defect if not
    if recent_d <= 2:
        return 'C'

    # Moderate cooperation rate: soft tit-for-tat
    if coop_rate >= 0.5:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    # Low cooperation rate: defect more
    if rng.random() < 0.6:
        return 'D'
    return 'C'
